class SyFinansCalismaProfili:
    def __init__(
        self,
        *,
        merkez: FinansKaynakMerkezi,
        oncelikli_varliklar: Iterable[
            OncelikliVarlik
        ] = (),
    ) -> None:
        self.merkez = merkez

        self._oncelikli_varliklar: dict[
            tuple[
                str,
                VarlikTuru,
            ],
            OncelikliVarlik,
        ] = {}

        for varlik in oncelikli_varliklar:
            self.varlik_ekle(
                varlik
            )

    @classmethod
    def varsayilan(
        cls,
        *,
        tcmb: (
            TcmbGuvenliBagdastiricisi
            | None
        ) = None,
        kap: (
            KapBildirimBagdastiricisi
            | None
        ) = None,
        tefas: (
            TefasFonBagdastiricisi
            | None
        ) = None,
        bist: (
            BistPiyasaBagdastiricisi
            | None
        ) = None,
        oncelikli_varliklar: Iterable[
            OncelikliVarlik
        ] = (),
    ) -> SyFinansCalismaProfili:
        piyasa_kaynaklari = [
            kaynak
            for kaynak in (
                tcmb,
                tefas,
                bist,
            )
            if kaynak is not None
        ]

        kap_kaynaklari = [
            kaynak
            for kaynak in (
                kap,
            )
            if kaynak is not None
        ]

        merkez = FinansKaynakMerkezi(
            piyasa_kaynaklari=(
                piyasa_kaynaklari
            ),
            kap_kaynaklari=(
                kap_kaynaklari
            ),
        )

        return cls(
            merkez=merkez,
            oncelikli_varliklar=(
                oncelikli_varliklar
            ),
        )

    def varlik_ekle(
        self,
        varlik: OncelikliVarlik,
    ) -> None:
        anahtar = (
            varlik.sembol
            .strip()
            .upper(),
            varlik.varlik_turu,
        )

        self._oncelikli_varliklar[
            anahtar
        ] = OncelikliVarlik(
            sembol=anahtar[0],
            varlik_turu=(
                varlik.varlik_turu
            ),
            oncelik=varlik.oncelik,
            kullanici_etiketi=(
                varlik.kullanici_etiketi
            ),
        )

    def varlik_sil(
        self,
        *,
        sembol: str,
        varlik_turu: VarlikTuru,
    ) -> bool:
        anahtar = (
            str(sembol)
            .strip()
            .upper(),
            varlik_turu,
        )

        return (
            self._oncelikli_varliklar
            .pop(
                anahtar,
                None,
            )
            is not None
        )

    def oncelikli_varliklar(
        self,
    ) -> tuple[
        OncelikliVarlik,
        ...
    ]:
        return tuple(
            sorted(
                self._oncelikli_varliklar
                .values(),
                key=lambda varlik: (
                    -varlik.oncelik,
                    varlik.varlik_turu.value,
                    varlik.sembol,
                ),
            )
        )

    def varlik_verisi_getir(
        self,
        *,
        sembol: str,
        varlik_turu: VarlikTuru,
    ) -> MerkeziPiyasaSonucu:
        return (
