        GrafikDonemi.GUNLUK: 1,
        GrafikDonemi.HAFTALIK: 7,
        GrafikDonemi.AYLIK: 31,
    }

    def __init__(
        self,
        *,
        depo: FiyatGecmisDeposu,
    ) -> None:
        self.depo = depo

    @staticmethod
    def _doneme_gore_filtrele(
        kayitlar: Iterable[
            FiyatGecmisKaydi
        ],
        *,
        donem: GrafikDonemi,
    ) -> tuple[
        FiyatGecmisKaydi,
        ...
    ]:
        sirali = tuple(
            sorted(
                kayitlar,
                key=lambda kayit: (
                    kayit.zaman
