            sirali[-1].zaman
        )

        gun_sayisi = (
            FinansGrafikMotoru
            .DONEM_GUNLERI[
                donem
            ]
        )

        return tuple(
            kayit
            for kayit in sirali
            if (
                son_zaman
                - datetime.fromisoformat(
                    kayit.zaman
                )
            ).total_seconds()
            <= gun_sayisi * 86400
        )

