@dataclass
class ResearchConceptProposalEngine:
    review_threshold: float = 0.60
    minimum_evidence_count: int = 1
    known_fingerprints: set[str] = field(
        default_factory=set
    )

    def propose(
        self,
        candidate: ConceptCandidate,
    ) -> ResearchConceptProposal:
        fingerprint = self._fingerprint(candidate)

        if fingerprint in self.known_fingerprints:
            return self._duplicate_proposal(
                candidate,
                fingerprint,
            )

        evidence_count = len(candidate.evidence)

        contradiction_count = sum(
            item.contradicts
            for item in candidate.evidence
        )

        confidence = self._confidence(
            candidate.evidence
        )

        uncertainty = self._uncertainty(
            evidence_count=evidence_count,
            contradiction_count=contradiction_count,
            unknown_count=len(candidate.unknown_fields),
        )

        priority = round(
            min(
                1.0,
                confidence * 0.45
                + uncertainty * 0.35
                + min(
                    1.0,
                    evidence_count / 5.0,
                )
                * 0.20,
            ),
            4,
        )

        status = self._status(
            confidence,
            evidence_count,
            contradiction_count,
        )

        proposal = ResearchConceptProposal(
            proposal_id=self._opaque_id(),
            internal_fingerprint=fingerprint,
            concept_name=candidate.concept_name.strip(),
            family=candidate.family,
            confidence_score=confidence,
            uncertainty_score=uncertainty,
            priority_score=priority,
            status=status,
            evidence_count=evidence_count,
            contradiction_count=contradiction_count,
            unknown_fields=tuple(
                candidate.unknown_fields
            ),
            user_explanation=self._user_explanation(
                candidate,
                confidence,
                contradiction_count,
            ),
        )

        self.known_fingerprints.add(fingerprint)

        return proposal

    def propose_many(
        self,
        candidates: Iterable[ConceptCandidate],
    ) -> list[ResearchConceptProposal]:
        proposals = [
            self.propose(candidate)
            for candidate in candidates
        ]

        proposals.sort(
            key=lambda item: (
                -item.priority_score,
                item.proposal_id,
            )
        )

        return proposals

    @staticmethod
    def _confidence(
        evidence_items: tuple[
            ResearchEvidence,
            ...,
        ],
    ) -> float:
        if not evidence_items:
            return 0.0

        weighted_total = 0.0
        weight_total = 0.0

        for item in evidence_items:
            weight = _SOURCE_WEIGHTS[
                item.source_quality
            ]

            direction = (
                -1.0
                if item.contradicts
                else 1.0
            )

            weighted_total += (
                item.support_score
                * weight
                * direction
            )

            weight_total += weight

        return round(
            max(
                0.0,
                min(
                    1.0,
                    weighted_total / weight_total,
                ),
            ),
            4,
        )

    @staticmethod
    def _uncertainty(
        evidence_count: int,
        contradiction_count: int,
        unknown_count: int,
    ) -> float:
        evidence_gap = max(
            0.0,
            1.0
            - min(
                1.0,
                evidence_count / 4.0,
            ),
        )

        contradiction_effect = min(
            0.70,
            contradiction_count * 0.35,
        )

        unknown_effect = min(
            0.40,
            unknown_count * 0.08,
        )

        return round(
            min(
                1.0,
                evidence_gap
                + contradiction_effect
                + unknown_effect,
            ),
            4,
        )

    def _status(
        self,
        confidence: float,
        evidence_count: int,
        contradiction_count: int,
    ) -> ProposalStatus:
        if (
            evidence_count
            < self.minimum_evidence_count
        ):
            return (
                ProposalStatus.INSUFFICIENT_DATA
            )

        if (
            contradiction_count > 0
            or confidence
            >= self.review_threshold
        ):
            return ProposalStatus.REVIEW_REQUIRED

        return ProposalStatus.CANDIDATE

