                ?.requested_modules;

        return Array.isArray(requested)
            ? requested.map(normalize)
            : [];
    }

    function scoreModule(
        modulePayload,
        tabId
    ) {
        const rule = TAB_RULES[tabId];

        if (!rule) {
            return 0;
        }

        const text =
            moduleSearchText(modulePayload);

        const id =
            normalize(moduleId(modulePayload));

        const requested =
            requestedModuleIds();

        let score = 0;

        for (const alias of rule.aliases) {
            const normalizedAlias =
                normalize(alias);

            if (id === normalizedAlias) {
                score += 120;
            }
            else if (
                id.includes(normalizedAlias)
            ) {
                score += 80;
            }
            else if (
                text.includes(normalizedAlias)
            ) {
                score += 45;
            }
        }

        for (const requestedId of requested) {
            if (!requestedId) {
                continue;
            }

            const requestedMatchesTab =
                rule.aliases.some(
                    (alias) => {
                        const normalizedAlias =
                            normalize(alias);

                        return (
                            requestedId
                                === normalizedAlias
                            || requestedId.includes(
                                normalizedAlias
                            )
                            || normalizedAlias.includes(
                                requestedId
                            )
                        );
                    }
                );

            if (!requestedMatchesTab) {
                continue;
            }

            if (id === requestedId) {
                score += 150;
            }
            else if (
                id.includes(requestedId)
                || requestedId.includes(id)
            ) {
                score += 70;
            }
        }

        return score;
    }

    function selectModules(
        inventory,
        tabId
    ) {
        const scored = inventory
            .map((modulePayload) => ({
                modulePayload,
                score: scoreModule(
                    modulePayload,
                    tabId
                ),
            }))
            .filter(
                (item) => item.score > 0
            )
            .sort(
                (left, right) =>
                    right.score - left.score
            );

        const selected = [];
        const usedIds = new Set();

        for (const item of scored) {
            const id = moduleId(
                item.modulePayload
            );

            if (!id || usedIds.has(id)) {
                continue;
            }

            usedIds.add(id);
            selected.push(
                item.modulePayload
            );

            if (selected.length >= 4) {
                break;
            }
        }

        return selected;
    }

